import json
from typing import Any
from claude_agent_sdk import tool, create_sdk_mcp_server
from app.database import Database
from app.pending_questions import pending_question_store

MAX_RESULT_ROWS = 100


class DuckDBServer(dict):
    """Wraps McpSdkServerConfig (a TypedDict/dict) and exposes _tools for testing."""

    def __init__(self, config: dict, tools: list) -> None:
        super().__init__(config)
        self._tools = tools


def create_duckdb_server(db: Database, session_id: str = "default") -> "DuckDBServer":
    @tool(
        "execute_sql",
        "Execute a SQL query against the DuckDB database. Use this to query loaded tables, "
        "create views, or run any valid DuckDB SQL. Results are returned as JSON with columns, "
        "rows, and rowCount.",
        {"sql": str},
    )
    async def execute_sql(args: dict[str, Any]) -> dict[str, Any]:
        sql = args["sql"]
        try:
            result = await db.execute_query_async(sql)
            truncated_rows = result["rows"][:MAX_RESULT_ROWS]
            result_json = {
                "status": "success",
                "columns": result["columns"],
                "rows": truncated_rows,
                "rowCount": result["rowCount"],
            }
            content_text = json.dumps(result_json, default=str)
            return {"content": [{"type": "text", "text": content_text}]}
        except Exception as e:
            error_json = {"status": "error", "error": str(e)}
            return {
                "content": [{"type": "text", "text": json.dumps(error_json)}],
                "is_error": True,
            }

    @tool(
        "ask_user_question",
        "Ask the user a clarifying question with selectable options. Use this when the user's "
        "request is ambiguous or when you need to choose between multiple valid approaches. "
        "The tool will pause and wait for the user to select an option before continuing. "
        "Always provide clear, concise options. The user can also type a free-text response.",
        {
            "type": "object",
            "properties": {
                "question": {"type": "string", "description": "The question to ask the user"},
                "options": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "List of option strings the user can select from",
                },
                "multi_select": {
                    "type": "boolean",
                    "description": "Whether the user can select multiple options",
                },
            },
            "required": ["question", "options"],
        },
    )
    async def ask_user_question(args: dict[str, Any]) -> dict[str, Any]:
        question_data = {
            "question": args["question"],
            "options": args.get("options", []),
            "multi_select": args.get("multi_select", False),
        }
        timeout = args.get("timeout", 300.0)  # Internal override for testing
        question_id = pending_question_store.create(session_id, question_data)
        answer = await pending_question_store.wait(session_id, question_id, timeout=timeout)
        if answer is None:
            result = {"timeout": True, "message": "User did not respond within the time limit."}
        else:
            result = answer
        return {"content": [{"type": "text", "text": json.dumps(result)}]}

    tools = [execute_sql, ask_user_question]
    config = create_sdk_mcp_server(
        name="duckdb",
        version="1.0.0",
        tools=tools,
    )
    return DuckDBServer(config, tools)

async def stream_chat(
    message: str,
    session_id: str | None = None,
    db: Database | None = None,
    conversation_history: list[dict] | None = None,
    langfuse_session_id: str | None = None,
    backend_session_id: str | None = None,
) -> AsyncIterator[str]:
    """Stream agent chat responses as SSE events."""
    if CONTAINER_ENABLED:
        from app.container_manager import container_manager
        if container_manager is None:
            logger.error(
                "CONTAINER_ENABLED=true but Docker is not available. "
                "Falling back to subprocess mode."
            )
        else:
            async for event in _stream_chat_container(
                message, session_id, db, conversation_history, container_manager,
                backend_session_id=backend_session_id,
                langfuse_session_id=langfuse_session_id,
            ):
                yield event
            return

    if db is None:
        raise ValueError("db must be provided")
    stable_session = backend_session_id or "default"
    duckdb_server = create_duckdb_server(db, session_id=stable_session)

    logger.info("Using model: %s", ANTHROPIC_MODEL)

    # Collect stderr from the CLI subprocess for debugging
    stderr_lines: list[str] = []

    # Use the --resume flag to continue an existing session
    session_token = proxy_token_store.create_token()
    options = ClaudeAgentOptions(
        model=ANTHROPIC_MODEL,
        system_prompt=build_system_prompt(db),
        mcp_servers={"duckdb": duckdb_server},
        allowed_tools=["Task", "mcp__duckdb__execute_sql", "mcp__duckdb__ask_user_question"],
        agents=build_subagent_definitions(db),
        permission_mode="bypassPermissions",
        max_turns=20,
        include_partial_messages=True,
        stderr=lambda line: stderr_lines.append(line),
        env={
            "ANTHROPIC_API_KEY": session_token,
            "ANTHROPIC_BASE_URL": f"{PROXY_BASE_URL}/anthropic",
            # Scrub Langfuse credentials so the agent subprocess cannot
            # read them from the inherited environment.
            "LANGFUSE_PUBLIC_KEY": "",
            "LANGFUSE_SECRET_KEY": "",
        },
        **({"resume": session_id} if session_id else {}),
    )

    # When editing, prepend conversation history to the user message
    # instead of bloating the system prompt
    query_message = _build_message_with_history(message, conversation_history)

    client = ClaudeSDKClient(options=options)
    # Will be set from the CLI's ResultMessage; use the passed-in value until then
    actual_session_id = session_id
    waiting_for_user = False

    # --- Langfuse OTel tracing setup (conditional) ---
    # Deferred: session_id is set after the CLI returns it in ResultMessage
    langfuse = get_langfuse_client()
    observation_ctx = None
    propagate_ctx = None
    if langfuse:
        try:
            trace_input: dict = {"message": message[:500]}
            if conversation_history:
                trace_input["conversation_history"] = conversation_history
            observation_ctx = langfuse.start_as_current_observation(
                name="agent-chat",
                input=trace_input,
                metadata={"model": ANTHROPIC_MODEL},
            )
            observation_ctx.__enter__()

            # Propagate the stable conversation session_id for child spans
            effective_langfuse_session_id = langfuse_session_id or session_id
            if effective_langfuse_session_id:
                from langfuse import propagate_attributes
                propagate_ctx = propagate_attributes(session_id=effective_langfuse_session_id)
                propagate_ctx.__enter__()
        except Exception as e:
            logger.debug("Failed to set up Langfuse tracing context: %s", e)
            observation_ctx = None

    try:
        await client.connect()
        await client.query(query_message, session_id=session_id or "default")

        has_tool_calls = False
        has_thinking = False
        done_sent = False
        sql_result_ids: set[str] = set()
        tool_names: dict[str, str] = {}
        # Track subagent text output from intermediate messages.
        # The SDK's Task tool_result often contains only metadata
        # (agentId, usage), not the subagent's actual output.  The real
        # output arrives in messages whose parent_tool_use_id matches
        # the Task tool ID.
        subagent_texts: dict[str, str] = {}
        tool_sqls: dict[str, str] = {}

        response_iter = client.receive_response().__aiter__()
        while True:
            try:
                if waiting_for_user:
                    try:
                        msg = await asyncio.wait_for(response_iter.__anext__(), timeout=5.0)
                    except asyncio.TimeoutError:
                        yield ": keepalive\n\n"
                        continue
                else:
                    msg = await response_iter.__anext__()
            except StopAsyncIteration:
                break

            waiting_for_user = False

            if isinstance(msg, StreamEvent):
                event = msg.event
                event_type = event.get("type", "")
                stream_parent = msg.parent_tool_use_id
                is_subagent_event = bool(stream_parent and stream_parent in tool_names)

                if event_type == "content_block_delta":
                    delta = event.get("delta", {})
                    delta_type = delta.get("type", "")
                    if delta_type == "thinking_delta":
                        text = delta.get("thinking", "")
                        if text and not is_subagent_event:
                            yield f"event: thinking\ndata: {json.dumps({'text': text})}\n\n"
                    elif delta_type == "text_delta":
                        text = delta.get("text", "")
                        if text:
                            if is_subagent_event:
                                subagent_texts[stream_parent] = subagent_texts.get(stream_parent, "") + text
                            else:
                                event_name = "thinking" if not has_tool_calls else "answer"
                                yield f"event: {event_name}\ndata: {json.dumps({'text': text})}\n\n"

                elif event_type == "content_block_start":
                    block = event.get("content_block", {})
                    block_type = block.get("type")
                    if block_type == "thinking":
                        if not is_subagent_event:
                            has_thinking = True
                    elif block_type == "text":
                        if has_thinking and not is_subagent_event:
                            yield f"event: thinking_done\ndata: {json.dumps({})}\n\n"
                    elif block_type == "tool_use":
                        if not is_subagent_event:
                            has_thinking = False
                            has_tool_calls = True

            elif isinstance(msg, AssistantMessage):
                is_subagent_msg = bool(msg.parent_tool_use_id and msg.parent_tool_use_id in tool_names)

                # Capture text from subagent assistant messages for chart_spec extraction
                if is_subagent_msg:
                    text_parts = []
                    for block in msg.content:
                        if hasattr(block, "text") and not isinstance(block, ToolUseBlock):
                            text_val = getattr(block, "text", "")
                            if text_val:
                                text_parts.append(text_val)
                    if text_parts:
                        subagent_texts[msg.parent_tool_use_id] = "\n".join(text_parts)

                for block in msg.content:
                    if isinstance(block, ToolUseBlock):
                        if not is_subagent_msg:
                            has_tool_calls = True
                        tool_name = getattr(block, "name", "") or ""
                        tool_names[block.id] = tool_name
                        is_execute_sql = "execute_sql" in tool_name
                        sql = block.input.get("sql", "") if is_execute_sql else ""
                        command = block.input.get("command", "")

                        # Track SQL for later tool_result matching
                        if sql:
                            tool_sqls[block.id] = sql

                        # Emit tool_call for ALL tool types (including subagent-internal)
                        tool_call_data: dict = {"id": block.id, "name": tool_name}
                        if sql:
                            tool_call_data["sql"] = sql
                        if command:
                            tool_call_data["command"] = command
                        if not sql and not command:
                            tool_call_data["input"] = block.input
                        yield f"event: tool_call\ndata: {json.dumps(tool_call_data, default=str)}\n\n"

                        # Orchestrator-specific handling (skip for subagent messages)
                        if not is_subagent_msg:
                            # Detect subagent invocation via Task tool
                            if tool_name == "Task":
                                subagent_type = block.input.get("subagent_type", "unknown")
                                tool_names[block.id] = subagent_type  # Store subagent name, not "Task"
                                yield f"event: subagent_start\ndata: {json.dumps({'id': block.id, 'name': subagent_type, 'prompt': block.input.get('prompt', '')})}\n\n"

                            # For execute_sql only, execute query for structured results
                            if sql:
                                sql_result_ids.add(block.id)
                                try:
                                    result = db.execute_query(sql)
                                    truncated = result["rows"][:100]
                                    yield f"event: tool_result\ndata: {json.dumps({'id': block.id, 'name': tool_name, 'sql': sql, 'columns': result['columns'], 'rows': truncated, 'rowCount': result['rowCount']}, default=str)}\n\n"
                                except Exception as e:
                                    yield f"event: tool_result\ndata: {json.dumps({'id': block.id, 'name': tool_name, 'sql': sql, 'error': str(e)})}\n\n"

                            # Detect ask_user_question tool
                            if "ask_user_question" in tool_name:
                                from app.pending_questions import pending_question_store
                                import asyncio as _asyncio
                                for _ in range(50):
                                    pending = pending_question_store.get_pending(stable_session)
                                    if pending:
                                        yield f"event: user_question\ndata: {json.dumps({'question_id': pending['question_id'], **pending['data']})}\n\n"
                                        waiting_for_user = True
                                        break
                                    await _asyncio.sleep(0.1)

            elif isinstance(msg, UserMessage):
                is_subagent_msg = bool(msg.parent_tool_use_id and msg.parent_tool_use_id in tool_names)

                # Process subagent-internal tool results (e.g. SQL query results)
                if is_subagent_msg:
                    content = msg.content
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, ToolResultBlock):
                                output = _extract_tool_result_text(block.content)
                                name = tool_names.get(block.tool_use_id, "")
                                result_data: dict = {"id": block.tool_use_id, "name": name}
                                original_sql = tool_sqls.get(block.tool_use_id, "")
                                if original_sql:
                                    result_data["sql"] = original_sql
                                if block.is_error:
                                    try:
                                        parsed_err = json.loads(output)
                                        result_data["error"] = parsed_err.get("error", output)
                                    except (json.JSONDecodeError, AttributeError):
                                        result_data["error"] = output
                                else:
                                    try:
                                        parsed = json.loads(output)
                                        if parsed.get("status") == "success":
                                            if "chart_spec" in parsed:
                                                result_data["chart_spec"] = parsed["chart_spec"]
                                            else:
                                                result_data["columns"] = parsed.get("columns", [])
                                                result_data["rows"] = parsed.get("rows", [])[:100]
                                                result_data["rowCount"] = parsed.get("rowCount", 0)
                                        elif parsed.get("status") == "error":
                                            result_data["error"] = parsed.get("error", "")
                                        else:
                                            result_data["output"] = output
                                    except (json.JSONDecodeError, AttributeError):
                                        result_data["output"] = output
                                yield f"event: tool_result\ndata: {json.dumps(result_data, default=str)}\n\n"
                    continue

                # The SDK attaches the subagent's actual output in
                # tool_use_result.content (a list of content blocks).
                tool_use_result_text = ""
                if msg.tool_use_result and isinstance(msg.tool_use_result, dict):
                    tur_content = msg.tool_use_result.get("content")
                    if isinstance(tur_content, list):
                        parts = []
                        for item in tur_content:
                            if isinstance(item, dict) and item.get("type") == "text":
                                parts.append(item.get("text", ""))
                        tool_use_result_text = "\n".join(parts)

                # Capture tool results from the SDK for non-SQL tools
                content = msg.content
                if isinstance(content, list):
                    for block in content:
                        if isinstance(block, ToolResultBlock):
                            if block.tool_use_id in sql_result_ids:
                                continue
                            output = _extract_tool_result_text(block.content)
                            name = tool_names.get(block.tool_use_id, "")
                            result_data: dict = {
                                "id": block.tool_use_id,
                                "name": name,
                            }
                            if block.is_error:
                                try:
                                    parsed_error = json.loads(output)
                                    result_data["error"] = parsed_error.get("error", output)
                                except (json.JSONDecodeError, AttributeError):
                                    result_data["error"] = output
                            else:
                                # Try to parse JSON output (e.g. chart_spec from chart-builder subagent)
                                try:
                                    parsed = json.loads(output)
                                    if parsed.get("status") == "success" and "chart_spec" in parsed:
                                        result_data["chart_spec"] = parsed["chart_spec"]
                                    else:
                                        result_data["output"] = output
                                except (json.JSONDecodeError, AttributeError):
                                    result_data["output"] = output
                            # Detect subagent result (Task tool)
                            if name in ("sql-analyst", "chart-builder"):
                                end_data: dict = {"id": block.tool_use_id, "name": name}
                                # Only chart-builder produces chart_spec JSON.
                                # sql-analyst returns plain text results.
                                if name == "chart-builder":
                                    chart_spec = _extract_chart_spec(output)
                                    if not chart_spec and tool_use_result_text:
                                        chart_spec = _extract_chart_spec(tool_use_result_text)
                                    if not chart_spec:
                                        captured = subagent_texts.get(block.tool_use_id, "")
                                        if captured:
                                            chart_spec = _extract_chart_spec(captured)
                                    if chart_spec:
                                        end_data["chart_spec"] = chart_spec
                                    else:
                                        end_data["result"] = tool_use_result_text or subagent_texts.get(block.tool_use_id, output)
                                        logger.warning(
                                            "chart_spec extraction failed for %s",
                                            name,
                                        )
                                else:
                                    end_data["result"] = tool_use_result_text or subagent_texts.get(block.tool_use_id, output)
                                yield f"event: subagent_end\ndata: {json.dumps(end_data, default=str)}\n\n"
                                continue  # Don't also emit tool_result for Task
                            yield f"event: tool_result\ndata: {json.dumps(result_data, default=str)}\n\n"

            elif isinstance(msg, ResultMessage):
                # Use the CLI's session_id so --resume can find it
                actual_session_id = msg.session_id or actual_session_id
                if msg.is_error and msg.result:
                    yield f"event: error\ndata: {json.dumps({'message': msg.result})}\n\n"
                yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
                done_sent = True

        # Guard: always send done even if SDK ended without ResultMessage
        if not done_sent:
            logger.warning("SDK stream ended without ResultMessage; sending done event")
            yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"

    except Exception as e:
        error_msg = str(e)
        if stderr_lines:
            error_msg += f" | CLI stderr: {' '.join(stderr_lines[-5:])}"
        logger.error("Agent error: %s", error_msg)
        yield f"event: error\ndata: {json.dumps({'message': error_msg})}\n\n"
        yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
    finally:
        proxy_token_store.revoke_token(session_token)
        # Update trace with the CLI's session_id so Langfuse session matches
        if langfuse and observation_ctx:
            try:
                trace_session_id = langfuse_session_id or actual_session_id
                langfuse.update_current_trace(
                    session_id=trace_session_id,
                    output={"session_id": actual_session_id},
                )
                if propagate_ctx:
                    propagate_ctx.__exit__(None, None, None)
                observation_ctx.__exit__(None, None, None)
            except Exception as e:
                logger.debug("Failed to finalize Langfuse trace: %s", e)
            try:
                langfuse.flush()
            except Exception as e:
                logger.debug("Failed to flush Langfuse: %s", e)

        try:
            await client.disconnect()
        except Exception:
            pass

    return None


def _extract_tool_result_text(content: object) -> str:
    """Extract text from ToolResultBlock.content."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text":
                parts.append(item.get("text", ""))
        return "\n".join(parts)
    return str(content)


async def _stream_chat_container(
    message: str,
    session_id: str | None,
    db: Database,
    conversation_history: list[dict] | None,
    container_manager,
    backend_session_id: str | None = None,
    langfuse_session_id: str | None = None,
) -> AsyncIterator[str]:
    """Stream chat via containerized sidecar instead of local subprocess."""
    import httpx
    import asyncio
